import { normalizeTicker } from "@/features/candlestick/candlestick-schema";
import type {
  CandlestickData,
  CandlestickRange,
} from "@/features/candlestick/candlestick-schema";

const sharedCandlestickRequests = new Map<
  string,
  { expiresAt: number; candles: Promise<CandlestickData> }
>();
const REUSE_MS = 60_000;

function candlestickKey(ticker: string, range: CandlestickRange) {
  return `${normalizeTicker(ticker) ?? ticker.trim().toUpperCase()}:${range}`;
}

async function fetchCandlestick(ticker: string, range: CandlestickRange) {
  const parameters = new URLSearchParams({ range, ticker });
  const response = await fetch(`/api/candlestick?${parameters}`);
  const body = (await response.json()) as CandlestickData | { error: string };
  if (!response.ok || "error" in body) {
    throw new Error(
      "error" in body ? body.error : `Chart request failed: ${response.status}`
    );
  }
  return body;
}

async function requestCandlestick(
  key: string,
  ticker: string,
  range: CandlestickRange
) {
  try {
    return await fetchCandlestick(ticker, range);
  } catch (error) {
    sharedCandlestickRequests.delete(key);
    throw error;
  }
}

export function loadCandlestick(
  ticker: string,
  range: CandlestickRange = "1m"
) {
  const key = candlestickKey(ticker, range);
  const hit = sharedCandlestickRequests.get(key);
  if (hit && Date.now() < hit.expiresAt) {
    return hit.candles;
  }
  const candles = requestCandlestick(key, ticker, range);
  sharedCandlestickRequests.set(key, {
    candles,
    expiresAt: Date.now() + REUSE_MS,
  });
  return candles;
}

export function primeCandlestick(
  ticker: string,
  range: CandlestickRange,
  data: CandlestickData
) {
  sharedCandlestickRequests.set(candlestickKey(ticker, range), {
    candles: Promise.resolve(data),
    expiresAt: Infinity,
  });
}

import "server-only";
import type {
  Candle,
  CandlestickData,
  CandlestickRange,
} from "@/features/candlestick/candlestick-schema";

// Server only: the endpoint doesn't allow browser requests (CORS).

/**
Yahoo's span and candle size for each range, picked so every range draws 20 to 55 candles.
*/
const YAHOO_RANGE: Record<
  CandlestickRange,
  { range: string; interval: string; every: number }
> = {
  "1d": { every: 15 * 60_000, interval: "15m", range: "1d" },
  "1m": { every: 86_400_000, interval: "1d", range: "1mo" },
  "1w": { every: 60 * 60_000, interval: "1h", range: "5d" },
  "1y": { every: 7 * 86_400_000, interval: "1wk", range: "1y" },
  "6m": { every: 7 * 86_400_000, interval: "1wk", range: "6mo" },
};

const NOT_FOUND = 404;
const MS_PER_SECOND = 1000;

/**
Tidies the end of Yahoo's series. After the close it adds a flat candle with no trades (the closing print), which would draw as a stray dash; and on weekly candles it splits the current week in two, a bar for the week so far and a bar for today, which belong in one candle.
*/
function tidyEnd(candles: Candle[], every: number): Candle[] {
  const last = candles.at(-1);
  const before = candles.at(-2);
  if (!(last && before)) {
    return candles;
  }
  const isClosingPrint =
    last.volume === 0 && last.high === last.low && before.volume > 0;
  if (isClosingPrint) {
    return candles.slice(0, -1);
  }
  if (last.time - before.time < every) {
    const merged: Candle = {
      close: last.close,
      high: Math.max(before.high, last.high),
      low: Math.min(before.low, last.low),
      open: before.open,
      time: before.time,
      volume: before.volume + last.volume,
    };
    return [...candles.slice(0, -2), merged];
  }
  return candles;
}

type Series = (number | null)[];

interface YahooQuote {
  open?: Series;
  high?: Series;
  low?: Series;
  close?: Series;
  volume?: Series;
}

interface YahooChart {
  chart: {
    result:
      | {
          meta: {
            symbol: string;
            currency?: string;
            longName?: string;
            shortName?: string;
            fullExchangeName?: string;
            exchangeName?: string;
            exchangeTimezoneName?: string;
            regularMarketPrice: number;
            regularMarketTime: number;
            chartPreviousClose?: number;
            previousClose?: number;
          };
          timestamp?: number[];
          indicators: { quote: YahooQuote[] };
        }[]
      | null;
    error: { code: string; description: string } | null;
  };
}

export class CandlestickNotFoundError extends Error {
  constructor(ticker: string, options?: ErrorOptions) {
    super(`No candles found for "${ticker}".`, options);
    this.name = "CandlestickNotFoundError";
  }
}

/**
Pairs Yahoo's parallel arrays into candles, skipping the gaps Yahoo leaves where a candle has no trades yet.
*/
function candlesOf(
  timestamps: readonly number[],
  quote: YahooQuote | undefined
): Candle[] {
  const candles: Candle[] = [];
  for (const [index, time] of timestamps.entries()) {
    const open = quote?.open?.[index];
    const high = quote?.high?.[index];
    const low = quote?.low?.[index];
    const close = quote?.close?.[index];
    const isTraded =
      typeof open === "number" &&
      typeof high === "number" &&
      typeof low === "number" &&
      typeof close === "number";
    if (isTraded) {
      candles.push({
        close,
        high,
        low,
        open,
        time: time * MS_PER_SECOND,
        volume: quote?.volume?.[index] ?? 0,
      });
    }
  }
  return candles;
}

/**
The candles for a ticker over a range. Pass it normalized (trimmed, upper case).
*/
export async function getCandlestick(
  ticker: string,
  range: CandlestickRange = "1m"
): Promise<CandlestickData> {
  const { range: yahooRange, interval, every } = YAHOO_RANGE[range];
  const url = `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(ticker)}?range=${yahooRange}&interval=${interval}`;

  const response = await fetch(url);
  if (response.status === NOT_FOUND) {
    throw new CandlestickNotFoundError(ticker);
  }
  if (!response.ok) {
    throw new Error(`The chart service returned ${response.status}.`);
  }

  const body = (await response.json()) as YahooChart;
  const result = body.chart.result?.[0];
  if (!result) {
    throw new CandlestickNotFoundError(ticker);
  }

  const { meta } = result;
  const candles = tidyEnd(
    candlesOf(result.timestamp ?? [], result.indicators.quote[0]),
    every
  );
  if (candles.length === 0) {
    throw new CandlestickNotFoundError(ticker);
  }

  const price = meta.regularMarketPrice;
  const base =
    range === "1d"
      ? (meta.chartPreviousClose ?? meta.previousClose ?? candles[0].open)
      : candles[0].open;
  const change = price - base;

  return {
    asOf: meta.regularMarketTime * MS_PER_SECOND,
    candles,
    change,
    changePercent: base ? (change / base) * 100 : 0,
    currency: meta.currency ?? "USD",
    exchange: meta.fullExchangeName ?? meta.exchangeName ?? "",
    name: meta.longName ?? meta.shortName ?? meta.symbol,
    price,
    range,
    ticker: meta.symbol,
    timeZone: meta.exchangeTimezoneName ?? "America/New_York",
  };
}

export const CANDLESTICK_RANGES = ["1d", "1w", "1m", "6m", "1y"] as const;
export type CandlestickRange = (typeof CANDLESTICK_RANGES)[number];

export const CANDLESTICK_RANGE_LABEL: Record<CandlestickRange, string> = {
  "1d": "1D",
  "1m": "1M",
  "1w": "1W",
  "1y": "1Y",
  "6m": "6M",
};

/**
How long each candle covers, for the card's footnote and the summary.
*/
export const CANDLE_SPAN: Record<CandlestickRange, string> = {
  "1d": "15-minute",
  "1m": "daily",
  "1w": "hourly",
  "1y": "weekly",
  "6m": "weekly",
};

const RANGE_PERIOD: Record<CandlestickRange, string> = {
  "1d": "today",
  "1m": "over the past month",
  "1w": "over the past week",
  "1y": "over the past year",
  "6m": "over the past six months",
};

export function isCandlestickRange(value: unknown): value is CandlestickRange {
  return (CANDLESTICK_RANGES as readonly unknown[]).includes(value);
}

export interface Candle {
  /**
  Unix time in milliseconds the candle opens at.
  */
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  /**
  Shares traded in the candle. Zero for an index, which has no volume.
  */
  volume: number;
}

export interface CandlestickData {
  ticker: string;
  name: string;
  /**
  e.g. "USD".
  */
  currency: string;
  exchange: string;
  /**
  The exchange's IANA time zone, e.g. "America/New_York". Candle times read in it.
  */
  timeZone: string;
  range: CandlestickRange;
  price: number;
  /**
  Change over the range: against the previous close for 1d, against the first candle's open otherwise.
  */
  change: number;
  changePercent: number;
  /**
  Oldest first.
  */
  candles: Candle[];
  /**
  Unix time in milliseconds of the latest price.
  */
  asOf: number;
}

const TICKER = /^[A-Z\d.^=-]{1,12}$/u;

/**
"nvda" and " NVDA " both read "NVDA". Null when it isn't a ticker.
*/
export function normalizeTicker(ticker: string): string | null {
  const trimmed = ticker.trim().toUpperCase();
  return TICKER.test(trimmed) ? trimmed : null;
}

/**
The message of a thrown error, or the fallback when something else was thrown. Uses instanceof rather than Error.isError, which Node 22 and older browsers don't have.
*/
export function errorMessage(error: unknown, fallback: string): string {
  // eslint-disable-next-line unicorn/prefer-error-is-error -- Error.isError is missing on Node 22 and older browsers
  return error instanceof Error ? error.message : fallback;
}

/**
The open, high, low and volume across a run of candles: the first open, the highest high, the lowest low, the last close and every share traded.
*/
export function spanOf(candles: readonly Candle[]): Candle | null {
  const [first] = candles;
  const last = candles.at(-1);
  if (!(first && last)) {
    return null;
  }
  let { high, low } = first;
  let volume = 0;
  for (const candle of candles) {
    high = Math.max(high, candle.high);
    low = Math.min(low, candle.low);
    volume += candle.volume;
  }
  return {
    close: last.close,
    high,
    low,
    open: first.open,
    time: first.time,
    volume,
  };
}

export function formatPrice(value: number, currency: string): string {
  try {
    const format = new Intl.NumberFormat("en-US", {
      currency,
      maximumFractionDigits: 2,
      minimumFractionDigits: 2,
      style: "currency",
    });
    return format.format(value);
  } catch {
    return `${value.toFixed(2)} ${currency}`;
  }
}

const AXIS_PRICE = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 2,
  minimumFractionDigits: 2,
});

/**
"247.30" for the price axis, where the currency sign would only crowd the labels.
*/
export function formatAxisPrice(value: number): string {
  return AXIS_PRICE.format(value);
}

/**
A time in the exchange's own zone, so a New York stock's first candle always reads 9:30 AM, and the server and the browser print the same thing.
*/
export function formatExchangeTime(
  time: number,
  timeZone: string,
  options: Intl.DateTimeFormatOptions
): string {
  const format = new Intl.DateTimeFormat("en-US", { ...options, timeZone });
  return format.format(time);
}

/**
One sentence the model (or a screen reader) can use to describe the card.
*/
export function summarizeCandlestick(data: CandlestickData): string {
  const direction = data.change >= 0 ? "up" : "down";
  const percent = `${Math.abs(data.changePercent).toFixed(2)}%`;
  const span = spanOf(data.candles);
  const extremes = span
    ? ` It ranged from ${formatPrice(span.low, data.currency)} to ${formatPrice(span.high, data.currency)}.`
    : "";
  return `${data.name} (${data.ticker}) is at ${formatPrice(data.price, data.currency)}, ${direction} ${percent} ${RANGE_PERIOD[data.range]}, shown as ${data.candles.length} ${CANDLE_SPAN[data.range]} candles.${extremes}`;
}

import {
  CandlestickNotFoundError,
  getCandlestick,
} from "@/features/candlestick/candlestick-queries";
import {
  errorMessage,
  isCandlestickRange,
  normalizeTicker,
} from "@/features/candlestick/candlestick-schema";

const CACHE = "public, s-maxage=60, stale-while-revalidate=300";

const BAD_REQUEST = 400;
const NOT_FOUND = 404;
const UPSTREAM_FAILED = 502;

// eslint-disable-next-line sonarjs/function-name -- Next.js route handlers must be named after the HTTP method
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const ticker = normalizeTicker(searchParams.get("ticker") ?? "");
  const range = searchParams.get("range") ?? "1m";

  if (!(ticker && isCandlestickRange(range))) {
    return Response.json(
      {
        error:
          "Pass a ticker such as NVDA, and optionally a range of 1d, 1w, 1m, 6m or 1y.",
      },
      { status: BAD_REQUEST }
    );
  }

  try {
    return Response.json(await getCandlestick(ticker, range), {
      headers: { "Cache-Control": CACHE },
    });
  } catch (error) {
    const status =
      error instanceof CandlestickNotFoundError ? NOT_FOUND : UPSTREAM_FAILED;
    return Response.json(
      { error: errorMessage(error, "Chart lookup failed.") },
      { status }
    );
  }
}

